const svgNs = 'http://www.w3.org/2000/svg';
const riskTokens = ['late', 'risk', 'ok', 'none'];
const ignoredTargets = 'a, button, input, select, textarea';
const editableTargets = 'textarea, select, [contenteditable]:not([contenteditable="false"]), '
    + 'input:not([readonly]):not([disabled]):not([type=checkbox]):not([type=radio]):not([type=button]):not([type=submit])'
    + ':not([type=reset]):not([type=range]):not([type=color]):not([type=file]):not([type=image])';

let root = null;
let dotNet = null;
let content = null;
let uid = '';
let underSvg = null;
let overSvg = null;
let lineLayer = null;
let overLayer = null;
let observer = null;
let frame = 0;
let pulseTimer = 0;
let pulseCard = null;
let items = [];
let adjacency = new Map();
let focusNodes = new Set();
let focusLines = new Set();
let hoverNode = null;
let instance = null;
let keysRoot = null;
let keysDotNet = null;
let keysInstance = null;

export function init(rootElement, dotNetRef, instanceId) {
    dispose();
    if (!rootElement || typeof rootElement.querySelector !== 'function') return;

    safely(() => {
        root = rootElement;
        dotNet = dotNetRef ?? null;
        instance = instanceId == null ? null : String(instanceId);
        uid = `dm${Date.now().toString(36)}${Math.random().toString(36).slice(2, 8)}`;
        createLayers();
        root.addEventListener('pointerover', onPointerOver);
        root.addEventListener('pointerout', onPointerOut);
        root.addEventListener('click', onClick);
        root.addEventListener('keydown', onKeyDown);
        root.addEventListener('focusin', onFocusIn);
        if (typeof ResizeObserver === 'function') {
            observer = new ResizeObserver(schedule);
        }
        attachLayers();
        const fonts = document.fonts;
        if (fonts && fonts.ready && typeof fonts.ready.then === 'function') {
            fonts.ready.then(schedule, () => null);
        }
        schedule();
    });
}

export function setLines(lines) {
    safely(() => {
        if (!root) return;
        const list = Array.isArray(lines) ? lines.map(normalizeLine).filter(line => line !== null) : [];
        buildLines(list);
        schedule();
    });
}

export function setFocus(nodeIds, lineKeys) {
    safely(() => {
        if (!root) return;
        focusNodes = new Set(toList(nodeIds));
        focusLines = new Set(toList(lineKeys));
        applyFocus();
        refreshOver();
        schedule();
    });
}

export function redraw() {
    safely(schedule);
}

export function scrollToNode(nodeId) {
    safely(() => {
        if (!root || nodeId == null) return;
        attachLayers();
        const card = cardOf(String(nodeId));
        if (!card) return;

        const header = content.querySelector('.dm-header');
        const laneHead = content.querySelector('.dm-lanehead');
        const style = card.style;
        const marginTop = style.scrollMarginTop;
        const marginLeft = style.scrollMarginLeft;
        style.scrollMarginTop = `${(header ? header.offsetHeight : 0) + 8}px`;
        style.scrollMarginLeft = `${(laneHead ? laneHead.offsetWidth : 0) + 8}px`;
        card.scrollIntoView({ behavior: 'smooth', block: 'nearest', inline: 'center' });
        style.scrollMarginTop = marginTop;
        style.scrollMarginLeft = marginLeft;

        pulse(card);
        card.focus({ preventScroll: true });
    });
}

export function replaceUrl(uri) {
    if (typeof uri !== 'string' || uri.length === 0) return;
    try {
        history.replaceState(history.state, '', uri);
    } catch (err) {
        console.warn('dependencyMap', 'replaceUrl', err);
    }
}

export function bindKeys(pageElement, dotNetRef, instanceId) {
    unbindKeys();
    if (!pageElement || typeof pageElement.contains !== 'function') return;
    keysRoot = pageElement;
    keysDotNet = dotNetRef ?? null;
    keysInstance = instanceId == null ? null : String(instanceId);
    document.addEventListener('keydown', onPageKeyDown);
    document.addEventListener('focusin', onPageFocusIn);
}

export function unbindKeys(instanceId) {
    if (instanceId != null && keysInstance !== null && String(instanceId) !== keysInstance) return;
    document.removeEventListener('keydown', onPageKeyDown);
    document.removeEventListener('focusin', onPageFocusIn);
    keysRoot = null;
    keysDotNet = null;
    keysInstance = null;
}

export function focusFullScreen(pageElement) {
    safely(() => {
        const overlay = fullScreenOf(pageElement);
        if (overlay) focusTarget(overlay).focus({ preventScroll: true });
    });
}

export function readStorage(prefix) {
    const values = {};
    try {
        for (let i = 0; i < localStorage.length; i++) {
            const key = localStorage.key(i);
            if (key && key.startsWith(String(prefix))) values[key] = localStorage.getItem(key);
        }
    } catch (err) {
        console.warn('dependencyMap', 'readStorage', err);
    }
    return values;
}

export function dispose(instanceId) {
    if (instanceId != null && instance !== null && String(instanceId) !== instance) return;
    safely(teardown);
    root = null;
    dotNet = null;
    content = null;
    uid = '';
    underSvg = null;
    overSvg = null;
    lineLayer = null;
    overLayer = null;
    observer = null;
    frame = 0;
    pulseTimer = 0;
    pulseCard = null;
    items = [];
    adjacency = new Map();
    focusNodes = new Set();
    focusLines = new Set();
    hoverNode = null;
    instance = null;
}

function teardown() {
    if (frame) cancelAnimationFrame(frame);
    if (pulseTimer) clearTimeout(pulseTimer);
    if (pulseCard) pulseCard.classList.remove('dm-pulse');
    if (observer) observer.disconnect();
    if (root) {
        root.removeEventListener('pointerover', onPointerOver);
        root.removeEventListener('pointerout', onPointerOut);
        root.removeEventListener('click', onClick);
        root.removeEventListener('keydown', onKeyDown);
        root.removeEventListener('focusin', onFocusIn);
        root.classList.remove('dm-hovering', 'dm-focusing');
        for (const node of root.querySelectorAll('.dm-hot, .dm-hot-n')) {
            node.classList.remove('dm-hot', 'dm-hot-n');
        }
    }
    if (underSvg) underSvg.remove();
    if (overSvg) overSvg.remove();
}

function safely(action) {
    try {
        action();
    } catch (err) {
        console.error('dependencyMap', err);
    }
}

function call(method, argument) {
    invoke(dotNet, method, argument);
}

function invoke(target, method, argument) {
    if (!target || typeof target.invokeMethodAsync !== 'function') return;
    try {
        const pending = argument === undefined
            ? target.invokeMethodAsync(method)
            : target.invokeMethodAsync(method, argument);
        if (pending && typeof pending.catch === 'function') {
            pending.catch(() => null);
        }
    } catch (err) {
        console.warn('dependencyMap', method, err);
    }
}

function make(name, attributes, text) {
    const node = document.createElementNS(svgNs, name);
    if (attributes) {
        for (const [key, value] of Object.entries(attributes)) {
            node.setAttribute(key, String(value));
        }
    }
    if (text != null) node.textContent = text;
    return node;
}

function createSvg() {
    const node = make('svg', { class: 'dm-svg', width: 0, height: 0, 'aria-hidden': 'true', focusable: 'false' });
    node.style.cssText = 'position:absolute;left:0;top:0;overflow:visible;pointer-events:none';
    return node;
}

function createLayers() {
    underSvg = createSvg();
    const defs = make('defs');
    for (const risk of riskTokens) {
        const marker = make('marker', {
            id: `${uid}-a-${risk}`,
            viewBox: '0 0 10 10',
            refX: 9,
            refY: 5,
            markerUnits: 'userSpaceOnUse',
            markerWidth: 10,
            markerHeight: 10,
            orient: 'auto-start-reverse'
        });
        marker.appendChild(make('path', { d: 'M0,0 L10,5 L0,10 z', class: `dm-mk-${risk}`, fill: 'currentColor' }));
        defs.appendChild(marker);
    }
    lineLayer = make('g');
    underSvg.append(defs, lineLayer);
    overSvg = createSvg();
    overLayer = make('g');
    overSvg.appendChild(overLayer);
}

function attachLayers() {
    if (!root || !underSvg) return false;
    const found = root.querySelector('.dm-content');
    if (!found) return false;
    if (found !== content) {
        content = found;
        if (observer) {
            observer.disconnect();
            observer.observe(found);
        }
    }
    const under = found.querySelector('.dm-under');
    const over = found.querySelector('.dm-over');
    if (!under || !over) return false;
    if (underSvg.parentNode !== under) under.appendChild(underSvg);
    if (overSvg.parentNode !== over) over.appendChild(overSvg);
    return true;
}

function normalizeLine(line) {
    if (!line || line.k == null || line.a == null || line.b == null) return null;
    const count = Number(line.n);
    return {
        k: String(line.k),
        a: String(line.a),
        b: String(line.b),
        d: Boolean(line.d),
        w: Boolean(line.w),
        r: riskTokens.includes(line.r) ? line.r : 'none',
        n: Number.isFinite(count) ? Math.floor(count) : 0,
        t: line.t == null ? '' : String(line.t)
    };
}

function toList(value) {
    if (value == null) return [];
    if (typeof value === 'string') return [value];
    return Array.from(value, item => String(item));
}

function buildLines(list) {
    adjacency = new Map();
    items = list.map((line, index) => {
        addAdjacent(line.a, index);
        if (line.b !== line.a) addAdjacent(line.b, index);
        return createLine(line);
    });
    const fragment = document.createDocumentFragment();
    for (const item of items) {
        fragment.appendChild(item.g);
    }
    lineLayer.replaceChildren(fragment);
    applyFocus();
    applyHover();
}

function addAdjacent(nodeId, index) {
    const list = adjacency.get(nodeId);
    if (list) {
        list.push(index);
    } else {
        adjacency.set(nodeId, [index]);
    }
}

function createLine(line) {
    const g = make('g', { class: `dm-line r-${line.r}${line.d ? '' : ' dm-undirected'}`, 'data-k': line.k });
    g.style.display = 'none';
    const marker = `url(#${uid}-a-${line.r})`;
    const path = make('path', { class: 'dm-path', fill: 'none', stroke: 'currentColor' });
    if (line.d) path.setAttribute('marker-end', marker);
    if (line.d && line.w) path.setAttribute('marker-start', marker);
    const hit = make('path', { class: 'dm-hit', fill: 'none', stroke: 'transparent', 'stroke-width': 12, 'pointer-events': 'stroke' });
    hit.appendChild(make('title', null, line.t));
    g.append(path, hit);

    let bang = null;
    if (line.r === 'late') {
        bang = make('g', { class: 'dm-bang', 'pointer-events': 'none' });
        bang.append(
            make('circle', { r: 7 }),
            make('text', { 'text-anchor': 'middle', 'dominant-baseline': 'central', 'font-size': 10, 'font-weight': 700 }, '!'));
        g.appendChild(bang);
    }

    let count = null;
    if (line.n > 1) {
        const label = `\u00d7${line.n}`;
        const width = 8 + label.length * 6;
        count = make('g', { class: 'dm-count', 'pointer-events': 'none' });
        count.append(
            make('rect', { x: -width / 2, y: -7, width, height: 14, rx: 7 }),
            make('text', { 'text-anchor': 'middle', 'dominant-baseline': 'central', 'font-size': 10, fill: 'currentColor' }, label));
        g.appendChild(count);
    }

    return { line, g, path, hit, bang, count };
}

function applyFocus() {
    if (root) root.classList.toggle('dm-focusing', focusNodes.size > 0 || focusLines.size > 0);
    for (const item of items) {
        item.g.classList.toggle('dm-in-focus', focusLines.has(item.line.k));
    }
}

function applyHover() {
    if (!root) return;
    attachLayers();
    if (content) {
        for (const node of content.querySelectorAll('.dm-hot, .dm-hot-n')) {
            node.classList.remove('dm-hot', 'dm-hot-n');
        }
    }
    for (const item of items) {
        item.g.classList.remove('dm-hot');
    }

    const card = cardOf(hoverNode);
    if (!card) hoverNode = null;
    root.classList.toggle('dm-hovering', card !== null);
    if (card) {
        card.classList.add('dm-hot');
        for (const index of adjacency.get(hoverNode) ?? []) {
            const { line, g } = items[index];
            g.classList.add('dm-hot');
            const other = cardOf(line.a === hoverNode ? line.b : line.a);
            if (other) other.classList.add('dm-hot-n');
        }
    }
    refreshOver();
}

function refreshOver() {
    if (!overLayer) return;
    const fragment = document.createDocumentFragment();
    for (const { g } of items) {
        if (g.style.display === 'none') continue;
        if (!g.classList.contains('dm-hot') && !g.classList.contains('dm-in-focus')) continue;
        const copy = g.cloneNode(true);
        const hit = copy.querySelector('.dm-hit');
        if (hit) hit.style.pointerEvents = 'none';
        fragment.appendChild(copy);
    }
    overLayer.replaceChildren(fragment);
}

function cardOf(nodeId) {
    if (!content || nodeId == null) return null;
    return content.querySelector(`[data-node="${escapeValue(nodeId)}"]`);
}

function escapeValue(value) {
    const css = globalThis.CSS;
    return css && typeof css.escape === 'function' ? css.escape(value) : String(value).replace(/["\\]/g, '\\$&');
}

function nodeOf(target) {
    if (!root || !target || typeof target.closest !== 'function') return null;
    const card = target.closest('[data-node]');
    return card && root.contains(card) ? card : null;
}

function onPointerOver(e) {
    const card = nodeOf(e.target);
    const nodeId = card ? card.getAttribute('data-node') : null;
    if (nodeId === hoverNode) return;
    hoverNode = nodeId;
    applyHover();
}

function onPointerOut(e) {
    if (!hoverNode) return;
    const card = nodeOf(e.target);
    if (!card) return;
    if (e.relatedTarget && card.contains(e.relatedTarget)) return;
    hoverNode = null;
    applyHover();
}

function onClick(e) {
    const target = e.target;
    if (e.defaultPrevented || !root || !target || typeof target.closest !== 'function') return;
    if (target.closest(ignoredTargets)) return;
    const card = nodeOf(target);
    if (card) {
        if (e.detail > 1) return;
        const nodeId = card.getAttribute('data-node');
        if (nodeId) call('OnJsActivate', nodeId);
        return;
    }
    const g = target.closest('g.dm-line');
    if (g && underSvg && underSvg.contains(g)) {
        const key = g.getAttribute('data-k');
        if (key) call('OnJsLine', key);
    }
}

function onFocusIn(e) {
    const card = nodeOf(e.target);
    if (!card || card !== e.target) return;
    let keyboard = true;
    try {
        keyboard = card.matches(':focus-visible');
    } catch (err) {
        keyboard = true;
    }
    if (keyboard) card.scrollIntoView({ block: 'nearest', inline: 'nearest' });
}

function onKeyDown(e) {
    if (e.defaultPrevented || !root) return;
    if (e.key !== 'Enter' && e.key !== ' ' && e.key !== 'Spacebar') return;
    if (e.altKey || e.ctrlKey || e.metaKey || e.repeat) return;
    const target = e.target;
    if (!target || typeof target.closest !== 'function' || target.closest(ignoredTargets)) return;
    const card = nodeOf(target);
    const nodeId = card ? card.getAttribute('data-node') : null;
    if (!nodeId) return;
    e.preventDefault();
    call('OnJsActivate', nodeId);
}

function onPageKeyDown(e) {
    if (e.defaultPrevented || !keysRoot || !keysRoot.isConnected) return;
    const target = e.target;
    if (!inPage(target) || isEditable(target)) return;
    if (e.key === 'Escape' && !e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
        if (!keysRoot.hasAttribute('data-close') && !keysRoot.hasAttribute('data-fullscreen')) return;
        e.preventDefault();
        invoke(keysDotNet, 'OnJsEscape');
        return;
    }
    if (e.key === 'ArrowLeft' && e.altKey && !e.ctrlKey && !e.metaKey && !e.shiftKey) {
        if (!keysRoot.hasAttribute('data-back')) return;
        e.preventDefault();
        invoke(keysDotNet, 'OnJsBack');
    }
}

function onPageFocusIn(e) {
    if (!keysRoot || !keysRoot.isConnected) return;
    const overlay = fullScreenOf(keysRoot);
    const target = e.target;
    if (!overlay || !target || typeof target.closest !== 'function' || overlay.contains(target)) return;
    if (target.closest('.mud-dialog-container, .mud-popover, .mud-snackbar')) return;
    focusTarget(overlay).focus({ preventScroll: true });
}

function fullScreenOf(pageElement) {
    if (!pageElement || typeof pageElement.querySelector !== 'function') return null;
    return pageElement.querySelector('.dm-fullscreen');
}

function focusTarget(overlay) {
    return overlay.querySelector('[data-dm-focus]') ?? overlay;
}

function inPage(target) {
    if (!target || target === document || target === document.body || target === document.documentElement) return true;
    return typeof target.nodeType === 'number' && keysRoot.contains(target);
}

function isEditable(target) {
    if (!target || typeof target.closest !== 'function') return false;
    return target.isContentEditable || target.closest(editableTargets) !== null;
}

function pulse(card) {
    if (pulseTimer) clearTimeout(pulseTimer);
    if (pulseCard) pulseCard.classList.remove('dm-pulse');
    card.classList.remove('dm-pulse');
    card.getBoundingClientRect();
    card.classList.add('dm-pulse');
    pulseCard = card;
    pulseTimer = setTimeout(() => {
        card.classList.remove('dm-pulse');
        if (pulseCard === card) pulseCard = null;
        pulseTimer = 0;
    }, 1200);
}

function schedule() {
    if (!root || frame) return;
    frame = requestAnimationFrame(() => {
        frame = 0;
        safely(draw);
    });
}

function draw() {
    if (!root || !attachLayers()) return;

    for (const node of [underSvg, overSvg]) {
        node.setAttribute('width', '0');
        node.setAttribute('height', '0');
    }
    const width = Math.ceil(Math.max(content.scrollWidth, content.offsetWidth));
    const height = Math.ceil(Math.max(content.scrollHeight, content.offsetHeight));
    const origin = underSvg.getBoundingClientRect();
    const overOrigin = overSvg.getBoundingClientRect();
    const rects = measureCards(origin);

    for (const node of [underSvg, overSvg]) {
        node.setAttribute('width', String(width));
        node.setAttribute('height', String(height));
    }
    const shiftX = origin.left - overOrigin.left;
    const shiftY = origin.top - overOrigin.top;
    if (Math.abs(shiftX) > 0.5 || Math.abs(shiftY) > 0.5) {
        overLayer.setAttribute('transform', `translate(${round(shiftX)},${round(shiftY)})`);
    } else {
        overLayer.removeAttribute('transform');
    }

    const routes = planRoutes(rects);
    items.forEach((item, index) => drawLine(item, routes[index]));
    applyFocus();
    applyHover();
}

function measureCards(origin) {
    const rects = new Map();
    for (const card of content.querySelectorAll('[data-node]')) {
        const nodeId = card.getAttribute('data-node');
        if (!nodeId || rects.has(nodeId)) continue;
        const r = card.getBoundingClientRect();
        if (r.width <= 0 || r.height <= 0) continue;
        const left = r.left - origin.left;
        const top = r.top - origin.top;
        rects.set(nodeId, { left, top, right: left + r.width, bottom: top + r.height, height: r.height });
    }
    return rects;
}

function planRoutes(rects) {
    const ports = new Map();
    const routes = items.map(({ line }) => {
        let from = line.a;
        let to = line.b;
        let a = rects.get(from);
        let b = rects.get(to);
        if (!a || !b || from === to) return null;
        if (!line.d && b.left < a.left) {
            [from, to, a, b] = [to, from, b, a];
        }

        let kind = 'same';
        if (b.left >= a.right - 4) {
            kind = 'forward';
        } else if (b.right <= a.left + 4) {
            kind = 'backward';
        }
        const route = {
            kind,
            sx: kind === 'backward' ? a.left : a.right,
            ex: kind === 'forward' ? b.left : b.right,
            sy: (a.top + a.bottom) / 2,
            ey: (b.top + b.bottom) / 2
        };
        addPort(ports, (kind === 'backward' ? 'l' : 'r') + from, { own: a, other: b, route, start: true, key: line.k });
        addPort(ports, (kind === 'forward' ? 'l' : 'r') + to, { own: b, other: a, route, start: false, key: line.k });
        return route;
    });
    for (const list of ports.values()) {
        spreadPorts(list);
    }
    return routes;
}

function addPort(ports, portKey, port) {
    port.y = (port.other.top + port.other.bottom) / 2;
    port.x = (port.other.left + port.other.right) / 2;
    const list = ports.get(portKey);
    if (list) {
        list.push(port);
    } else {
        ports.set(portKey, [port]);
    }
}

function spreadPorts(list) {
    list.sort((p, q) => p.y - q.y || p.x - q.x || compareText(p.key, q.key));
    const count = list.length;
    list.forEach((port, index) => {
        const { top, bottom, height } = port.own;
        const wanted = top + height * (index + 1) / (count + 1);
        const y = Math.min(bottom - height * 0.15, Math.max(top + height * 0.15, wanted));
        if (port.start) {
            port.route.sy = y;
        } else {
            port.route.ey = y;
        }
    });
}

function compareText(a, b) {
    if (a === b) return 0;
    return a < b ? -1 : 1;
}

function drawLine(item, route) {
    const { g, path, hit, bang, count } = item;
    if (!route) {
        g.style.display = 'none';
        return;
    }

    const { kind, sx, sy, ex, ey } = route;
    let c1 = Math.max(sx, ex) + 36;
    let c2 = c1;
    if (kind !== 'same') {
        const dx = Math.max(30, Math.abs(ex - sx) / 2);
        c1 = kind === 'forward' ? sx + dx : sx - dx;
        c2 = kind === 'forward' ? ex - dx : ex + dx;
    }
    const d = `M${round(sx)},${round(sy)} C${round(c1)},${round(sy)} ${round(c2)},${round(ey)} ${round(ex)},${round(ey)}`;
    path.setAttribute('d', d);
    hit.setAttribute('d', d);
    g.style.display = '';

    if (!bang && !count) return;
    const mid = midpoint(path, route, c1, c2);
    if (bang) bang.setAttribute('transform', `translate(${round(mid.x)},${round(mid.y)})`);
    if (count) count.setAttribute('transform', `translate(${round(mid.x)},${round(mid.y + (bang ? 15 : 0))})`);
}

function midpoint(path, route, c1, c2) {
    const fallback = { x: (route.sx + 3 * c1 + 3 * c2 + route.ex) / 8, y: (route.sy + route.ey) / 2 };
    try {
        const length = path.getTotalLength();
        if (!(length > 0)) return fallback;
        const point = path.getPointAtLength(length / 2);
        return { x: point.x, y: point.y };
    } catch (err) {
        console.debug('dependencyMap', err);
        return fallback;
    }
}

function round(value) {
    return Math.round(value * 10) / 10;
}
